    int len = digits.size();
    vector<vector<vector<vector<int>>>> memo(len + 1, vector<vector<vector<int>>>(2, vector<vector<int>>>(2, vector<int>(2, -1))));

    function<int(int, bool, bool, bool)> dp = [&](int pos, bool tight, bool started, bool valid) -> int {
        if (pos == len) {
            return (started && valid) ? 1 : 0;
        }
        if (memo[pos][tight][started][valid] != -1) {
            return memo[pos][tight][started][valid];
        }
        int limit = tight ? digits[pos] : 9;
        int res = 0;
        for (int d = 0; d <= limit; ++d) {
            bool new_tight = tight && (d == limit);
            bool new_started = started || (d != 0);
            bool new_valid;
            if (!new_started) {
                new_valid = true;
            } else {
                if (!started) {
                    new_valid = true;
                } else {
                    new_valid = valid && (d == 0 || d == 1);
                }
            }
            res += dp(pos + 1, new_tight, new_started, new_valid);
        }
        return memo[pos][tight][started][valid] = res;
    };

